insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Assam has a largely {{term:agrarian-economy|agrarian economy}}. Farming gives work to most of its people.$t$ from public.content where slug = $t$agriculture-and-crops$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 2, 'paragraph', 'verified_fact', $t$In 2021-22, agriculture made up about 25 percent of Assam's economy, industry about 30 percent and services about 45 percent.$t$ from public.content where slug = $t$agriculture-and-crops$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 3, 'heading', 'normal', $t$Main crops$t$ from public.content where slug = $t$agriculture-and-crops$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 4, 'paragraph', 'normal', $t$Rice is the {{term:staple-food|staple food}} of Assam and its main crop. It is grown in three seasons:$t$ from public.content where slug = $t$agriculture-and-crops$t$ on conflict do nothing;
