insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 6, 'paragraph', 'normal', $t$Tea is the most important cash crop. Other crops include jute, mustard, pulses, sugarcane, vegetables and fruits.$t$ from public.content where slug = $t$agriculture-and-crops$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 7, 'fact_box', 'exam_fact', $t$Remember for exams: sector shares 2021-22: agriculture 25%, industry 30%, services 45%.$t$ from public.content where slug = $t$agriculture-and-crops$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$কৃষি আৰু প্ৰধান শস্য$t$, $t$কৃষিয়ে অসমক কেনেকৈ চলাই ৰাখিছে, প্ৰতিটো খণ্ডৰ অংশ আৰু প্ৰধান শস্যসমূহ।$t$, 'draft', $t$Economy of Assam, Wikipedia: https://en.wikipedia.org/wiki/Economy_of_Assam
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$অসমৰ অৰ্থনীতি মূলতঃ {{term:agrarian-economy|কৃষিভিত্তিক}}। কৃষিয়ে ইয়াৰ বেছিভাগ মানুহক সংস্থাপন দিয়ে।$t$ from public.content where slug = $t$agriculture-and-crops$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 2, 'paragraph', 'verified_fact', $t$২০২১-২২ চনত অসমৰ অৰ্থনীতিত কৃষিৰ অংশ প্ৰায় ২৫ শতাংশ, উদ্যোগৰ প্ৰায় ৩০ শতাংশ আৰু সেৱা খণ্ডৰ প্ৰায় ৪৫ শতাংশ আছিল।$t$ from public.content where slug = $t$agriculture-and-crops$t$ on conflict do nothing;
