insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 6, 'paragraph', 'normal', $t$চাহ আটাইতকৈ গুৰুত্বপূৰ্ণ বাণিজ্যিক শস্য। আন শস্যৰ ভিতৰত আছে মৰাপাট, সৰিয়হ, মাহজাতীয় শস্য, কুঁহিয়াৰ, শাক-পাচলি আৰু ফল-মূল।$t$ from public.content where slug = $t$agriculture-and-crops$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 7, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: ২০২১-২২ত খণ্ডসমূহৰ অংশ: কৃষি ২৫%, উদ্যোগ ৩০%, সেৱা ৪৫%।$t$ from public.content where slug = $t$agriculture-and-crops$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$tea-industry$t$, 'gk_chapter', id, 2 from public.categories where slug = $t$economy$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$The tea industry$t$, $t$How Assam tea was found, the Assam Company, and Assam's place in tea today.$t$, 'draft', $t$Assam tea, Wikipedia: https://en.wikipedia.org/wiki/Assam_tea
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Assam is the world's largest tea-growing region by production. It grows about 680 million kg of tea a year, and in 2015 it produced about 60 percent of India's tea.$t$ from public.content where slug = $t$tea-industry$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 2, 'heading', 'normal', $t$How Assam tea was found$t$ from public.content where slug = $t$tea-industry$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 3, 'paragraph', 'event', $t$In 1823 a Scottish trader, Robert Bruce, came across the tea plant in Assam. Maniram Dewan directed him to the Singpho chief Bessa Gam, whose people used the plant. The Assam tea plant is a local variety, {{term:camellia-assamica|Camellia sinensis var. assamica}}.$t$ from public.content where slug = $t$tea-industry$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 4, 'paragraph', 'event', $t$The first Assam tea was shipped to London in 1838 and auctioned in January 1839. In 1839 the Assam Company was formed, and Maniram became its {{term:dewan|Dewan}} at Nazira.$t$ from public.content where slug = $t$tea-industry$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 5, 'paragraph', 'normal', $t$The Tocklai Tea Research Institute at Jorhat, set up in 1911, is one of the oldest tea research centres in the world.$t$ from public.content where slug = $t$tea-industry$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 6, 'fact_box', 'exam_fact', $t$Remember for exams: Robert Bruce found Assam tea in 1823; Assam Company formed in 1839.$t$ from public.content where slug = $t$tea-industry$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$চাহ উদ্যোগ$t$, $t$অসমৰ চাহ কেনেকৈ পোৱা গ'ল, আসাম কোম্পানী, আৰু আজিৰ চাহ উদ্যোগত অসমৰ স্থান।$t$, 'draft', $t$Assam tea, Wikipedia: https://en.wikipedia.org/wiki/Assam_tea
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$উৎপাদনৰ হিচাপত অসম পৃথিৱীৰ বৃহত্তম চাহ উৎপাদনকাৰী অঞ্চল। ইয়াত বছৰি প্ৰায় ৬৮ কোটি কিলোগ্ৰাম চাহ উৎপাদন হয়, আৰু ২০১৫ চনত ভাৰতৰ মুঠ চাহৰ প্ৰায় ৬০ শতাংশ অসমত উৎপাদন হৈছিল।$t$ from public.content where slug = $t$tea-industry$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h1', 2, 'heading', 'normal', $t$অসমৰ চাহ কেনেকৈ পোৱা গ'ল$t$ from public.content where slug = $t$tea-industry$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 3, 'paragraph', 'event', $t$১৮২৩ চনত স্কটলেণ্ডৰ বেপাৰী ৰবাৰ্ট ব্ৰুছে অসমত চাহ গছ দেখা পায়। মণিৰাম দেৱানে তেওঁক চিংফৌ মুখিয়াল বিছা গামৰ ওচৰলৈ পঠায়, যাৰ লোকসকলে এই গছ ব্যৱহাৰ কৰিছিল। অসমৰ চাহ গছ এবিধ স্থানীয় জাত, {{term:camellia-assamica|কেমেলিয়া চিনেনচিছ ভেৰ. আছামিকা}}।$t$ from public.content where slug = $t$tea-industry$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 4, 'paragraph', 'event', $t$১৮৩৮ চনত প্ৰথম অসমৰ চাহ লণ্ডনলৈ পঠোৱা হয় আৰু ১৮৩৯ চনৰ জানুৱাৰীত নিলাম হয়। ১৮৩৯ চনত আসাম কোম্পানী গঠন হয়, আৰু মণিৰাম নাজিৰাত ইয়াৰ {{term:dewan|দেৱান}} হয়।$t$ from public.content where slug = $t$tea-industry$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 5, 'paragraph', 'normal', $t$১৯১১ চনত স্থাপিত যোৰহাটৰ টোকলাই চাহ গৱেষণা প্ৰতিষ্ঠান পৃথিৱীৰ আটাইতকৈ পুৰণি চাহ গৱেষণা কেন্দ্ৰসমূহৰ এটা।$t$ from public.content where slug = $t$tea-industry$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 6, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: ১৮২৩ চনত ৰবাৰ্ট ব্ৰুছে অসমৰ চাহ পায়; ১৮৩৯ চনত আসাম কোম্পানী গঠন।$t$ from public.content where slug = $t$tea-industry$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$oil-and-natural-gas$t$, 'gk_chapter', id, 3 from public.categories where slug = $t$economy$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Oil and natural gas$t$, $t$Digboi, Asia's first refinery, and the four refineries of Assam.$t$, 'draft', $t$Digboi Refinery, Wikipedia: https://en.wikipedia.org/wiki/Digboi_Refinery
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Oil was first found by accident in the Digboi area in 1867, while a railway line was being laid. Drilling for oil began in 1889.$t$ from public.content where slug = $t$oil-and-natural-gas$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 2, 'paragraph', 'event', $t$The Digboi {{term:refinery}} was started by the Assam Oil Company and commissioned on 11 December 1901. It is Asia's first refinery and India's oldest refinery still working.$t$ from public.content where slug = $t$oil-and-natural-gas$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 3, 'heading', 'normal', $t$Refineries of Assam$t$ from public.content where slug = $t$oil-and-natural-gas$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 4, 'list', 'verified_fact', $t$Digboi (Tinsukia district), 1901
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 5, 'paragraph', 'normal', $t$Together the four refineries can process about 7 million tonnes of {{term:crude-oil|crude oil}} a year. The oil and gas fields are in the districts of Upper Assam.$t$ from public.content where slug = $t$oil-and-natural-gas$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 6, 'fact_box', 'exam_fact', $t$Remember for exams: Digboi refinery, 1901, Asia's first; drilling began 1889; Assam has 4 refineries.$t$ from public.content where slug = $t$oil-and-natural-gas$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$খাৰুৱা তেল আৰু প্ৰাকৃতিক গেছ$t$, $t$এছিয়াৰ প্ৰথম শোধনাগাৰ ডিগবৈ, আৰু অসমৰ চাৰিটা শোধনাগাৰ।$t$, 'draft', $t$Digboi Refinery, Wikipedia: https://en.wikipedia.org/wiki/Digboi_Refinery
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$১৮৬৭ চনত ৰেলপথ নিৰ্মাণৰ সময়ত ডিগবৈ অঞ্চলত আকস্মিকভাৱে প্ৰথম তেল পোৱা যায়। ১৮৮৯ চনত তেলৰ বাবে খনন আৰম্ভ হয়।$t$ from public.content where slug = $t$oil-and-natural-gas$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 2, 'paragraph', 'event', $t$আসাম অইল কোম্পানীয়ে আৰম্ভ কৰা ডিগবৈ {{term:refinery|শোধনাগাৰ}} ১৯০১ চনৰ ১১ ডিচেম্বৰত চালু হয়। ই এছিয়াৰ প্ৰথম শোধনাগাৰ আৰু এতিয়াও চলি থকা ভাৰতৰ আটাইতকৈ পুৰণি শোধনাগাৰ।$t$ from public.content where slug = $t$oil-and-natural-gas$t$ on conflict do nothing;
