insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 4, 'paragraph', 'heritage', $t${{term:sericulture|Sericulture}} is a major rural occupation. Assam rears Muga, Eri and Pat silkworms. {{term:muga-silk|Muga silk}} is produced only in Assam.$t$ from public.content where slug = $t$industries-and-sericulture$t$ on conflict do nothing;
