insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 4, 'paragraph', 'heritage', $t${{term:sericulture|পলুপোহা}} এক প্ৰধান গ্ৰাম্য বৃত্তি। অসমত মুগা, এৰী আৰু পাট পলু পোহা হয়। {{term:muga-silk|মুগা}} কেৱল অসমতহে উৎপাদন হয়।$t$ from public.content where slug = $t$industries-and-sericulture$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 5, 'paragraph', 'normal', $t${{term:gsdp|জি এছ ডি পি}}ৰ হিচাপত ২০১৬ ৰ পৰা ২০২৫ চনৰ ভিতৰত অসমৰ অৰ্থনীতি বছৰি প্ৰায় ৭ শতাংশ হাৰত (২০১১-১২ৰ স্থিৰ মূল্যত) বৃদ্ধি পাইছিল।$t$ from public.content where slug = $t$industries-and-sericulture$t$ on conflict do nothing;
